public interface IReportGenerator { Task GenerateAsync(); }

public class TransientReportGenerator : IReportGenerator
{
    private int _counter = 0;
    public Task GenerateAsync()
    {
        _counter++;
        Console.WriteLine($"Transient call #{_counter}");
        return Task.CompletedTask;
    }
}

// Registrations
builder.Services.AddTransient<IReportGenerator, TransientReportGenerator>();
builder.Services.AddScoped<IOrderRepository, OrderRepository>();
builder.Services.AddSingleton<ICacheService, InMemoryCacheService>();

public class BadSingletonCache
{
    private readonly AppDbContext _db;

    public BadSingletonCache(AppDbContext db)
    {
        // _db is captured from the first request that resolved the singleton
        _db = db;
    }
}

builder.Services.AddSingleton<BadSingletonCache>(); // throws at runtime
builder.Services.AddDbContext<AppDbContext>(...);
